-- No prices or departure dates are invented. Re-run safely: existing titles are skipped.

with tour_data(title,region,summary,tour_type,duration_days,duration_label,departure_point,transport,itinerary,operating_note) as (
 values
 ('Sài Gòn qua những lớp ký ức','Miền Nam','Đi bộ khám phá kiến trúc, không gian công cộng và những câu chuyện đô thị qua góc nhìn đời sống địa phương.','Di sản đô thị',1,'Nửa ngày','Trung tâm Quận 1, TP. Hồ Chí Minh','Đi bộ; phương tiện nội đô khi cần',
 '[{"time":"08:00–08:30","title":"Gặp nhau giữa lòng phố","description":"Làm quen với người dẫn chuyện và thống nhất tuyến đi bộ; giờ hẹn dự kiến, cần xác nhận điểm tập trung."},{"time":"08:30–10:00","title":"Đọc dấu ấn kiến trúc","description":"Quan sát mặt đứng công trình, không gian công cộng và các lớp lịch sử đô thị từ bên ngoài; việc vào tham quan tùy giờ mở cửa."},{"time":"10:00–11:00","title":"Nhịp sống địa phương","description":"Dừng tại một không gian sinh hoạt hoặc hàng quán địa phương phù hợp tuyến."},{"time":"11:00–11:30","title":"Khép lại câu chuyện","description":"Chia sẻ cảm nhận và gợi ý những điểm khám phá tiếp theo."}]'::jsonb,
 'Lịch trình đề xuất, không phải giờ vận hành đã xác nhận. Cần kiểm tra giờ mở cửa từng điểm, quyền tham quan và điều kiện đi bộ trước khi mở bán.'),
 ('Một ngày ở Củ Chi: đất và người','Miền Nam','Tìm hiểu câu chuyện vùng đất Củ Chi, cảnh quan nông thôn và đời sống cộng đồng qua hoạt động tìm hiểu có hướng dẫn.','Văn hóa – lịch sử',1,'1 ngày','Điểm hẹn tại TP. Hồ Chí Minh; xác nhận theo nhà tổ chức','Xe du lịch; đi bộ tại điểm',
 '[{"time":"07:00–08:30","title":"Di chuyển về Củ Chi","description":"Thời gian dự kiến; phụ thuộc điểm đón và giao thông."},{"time":"08:30–11:00","title":"Tìm hiểu di tích và bối cảnh lịch sử","description":"Tham quan khu di tích phù hợp, tuân thủ nội quy và hướng dẫn tại chỗ."},{"time":"11:00–13:00","title":"Ẩm thực và nghỉ trưa","description":"Dùng bữa theo phương án nhà tổ chức xác nhận; thực đơn chưa bao gồm trong bản đề xuất."},{"time":"13:00–15:30","title":"Gặp gỡ câu chuyện địa phương","description":"Hoạt động tìm hiểu đời sống và sản vật địa phương; cần đối tác cộng đồng xác nhận."},{"time":"15:30–17:00","title":"Trở về TP. Hồ Chí Minh","description":"Thời gian dự kiến theo tình hình giao thông."}]'::jsonb,
 'Cần xác minh đơn vị vận hành, vé vào cửa, địa điểm được phép tham quan, đối tác cộng đồng, phương tiện và thời gian di chuyển.'),
 ('Miền vườn Cái Bè – chậm một nhịp','Miền Nam','Khám phá cảnh quan sông nước, vườn cây và nhịp sống miệt vườn Tiền Giang theo hướng du lịch có trách nhiệm.','Đời sống bản địa',1,'1 ngày','Điểm hẹn tại TP. Hồ Chí Minh hoặc Cái Bè','Xe đường bộ; thuyền nếu đối tác đủ điều kiện',
 '[{"time":"06:30–09:00","title":"Đến vùng sông nước","description":"Di chuyển đến Cái Bè; thời gian thay đổi theo điểm đón và giao thông."},{"time":"09:00–10:30","title":"Khám phá không gian miệt vườn","description":"Thăm vườn đang đón khách theo mùa và nghe giới thiệu về canh tác."},{"time":"10:30–12:00","title":"Câu chuyện ven sông","description":"Tìm hiểu sinh hoạt địa phương; hoạt động thuyền chỉ tổ chức khi điều kiện an toàn và nhà cung cấp được xác nhận."},{"time":"12:00–14:00","title":"Bữa trưa địa phương","description":"Thưởng thức món ăn theo thực đơn được xác nhận trước."},{"time":"14:00–16:30","title":"Gặp gỡ và trở về","description":"Giao lưu với cơ sở địa phương, sau đó khởi hành về điểm hẹn."}]'::jsonb,
 'Trải nghiệm phụ thuộc mùa vụ, mực nước, thời tiết và sự đồng ý của chủ vườn. Cần xác minh bến đón, đơn vị thuyền, bảo hiểm và thực đơn.'),
 ('Đà Lạt – dấu chân cao nguyên','Miền Trung','Kết nối kiến trúc, cảnh quan cao nguyên và câu chuyện cư dân Đà Lạt trong hành trình khám phá chậm.','Thiên nhiên – văn hóa',2,'2 ngày 1 đêm','Đà Lạt; điểm đón cụ thể sẽ xác nhận','Xe du lịch; đi bộ',
 '[{"time":"Ngày 1 · 08:00–11:30","title":"Nhịp phố cao nguyên","description":"Khám phá một cụm kiến trúc và không gian công cộng; lựa chọn điểm theo giờ mở cửa."},{"time":"Ngày 1 · 11:30–13:30","title":"Ẩm thực địa phương","description":"Nghỉ trưa và dùng bữa theo phương án được xác nhận."},{"time":"Ngày 1 · 14:00–17:00","title":"Cảnh quan và câu chuyện cư dân","description":"Tham quan điểm cảnh quan phù hợp thời tiết, kết hợp nghe kể chuyện địa phương."},{"time":"Ngày 2 · 07:30–11:30","title":"Một buổi sáng xanh","description":"Khám phá vườn/không gian nông nghiệp đang đón khách; hoạt động theo mùa."},{"time":"Ngày 2 · 13:00–16:00","title":"Khép lại hành trình","description":"Thăm một không gian văn hóa phù hợp và kết thúc chương trình."}]'::jsonb,
 'Khung nội dung đề xuất. Cần chốt điểm tham quan, lưu trú, bữa ăn, thời gian di chuyển, mùa hoa/mùa vụ và phương án thời tiết trước khi công bố.'),
 ('Hội An – phố nhỏ, chuyện dài','Miền Trung','Tìm hiểu di sản đô thị Hội An, nghề thủ công và nhịp sống ven sông qua những điểm dừng có chọn lọc.','Di sản – thủ công',2,'2 ngày 1 đêm','Hội An; điểm hẹn xác nhận theo nơi lưu trú','Đi bộ; xe đạp nếu điều kiện phù hợp',
 '[{"time":"Ngày 1 · 08:00–10:30","title":"Đọc không gian phố cổ","description":"Đi bộ theo tuyến được phép, tìm hiểu kiến trúc và nếp sống; vé tham quan theo quy định hiện hành."},{"time":"Ngày 1 · 10:30–12:00","title":"Câu chuyện nghề thủ công","description":"Ghé cơ sở thủ công có nhận khách và được chủ cơ sở đồng ý."},{"time":"Ngày 1 · 14:00–17:00","title":"Ven sông và xóm phố","description":"Khám phá không gian ven sông, tôn trọng khu dân cư và giờ sinh hoạt."},{"time":"Ngày 2 · 08:00–11:00","title":"Ngoại vi và làng nghề","description":"Chọn một làng nghề/cộng đồng phù hợp, hoạt động theo lịch tiếp đón."},{"time":"Ngày 2 · 13:00–15:00","title":"Dư âm Hội An","description":"Tổng kết câu chuyện, thời gian tự do và kết thúc."}]'::jsonb,
 'Cần xác minh vé/phạm vi phố cổ, lịch nhận khách của cơ sở nghề, phương tiện, lưu trú, quy tắc chụp ảnh và sức chứa.'),
 ('Huế – sống cùng di sản','Miền Trung','Hành trình tìm hiểu di sản cố đô, kiến trúc và văn hóa ẩm thực Huế với nhịp điệu vừa phải.','Di sản – ẩm thực',2,'2 ngày 1 đêm','TP. Huế; điểm hẹn cụ thể sẽ xác nhận','Xe du lịch; đi bộ tại di tích',
 '[{"time":"Ngày 1 · 08:00–11:30","title":"Không gian Hoàng thành","description":"Tham quan theo tuyến và quy định hiện hành của đơn vị quản lý di tích."},{"time":"Ngày 1 · 11:30–14:00","title":"Ẩm thực Huế","description":"Dùng bữa theo thực đơn và yêu cầu ăn uống đã xác nhận."},{"time":"Ngày 1 · 14:00–17:00","title":"Dấu tích bên dòng Hương","description":"Khám phá một cụm di tích/không gian văn hóa phù hợp giờ mở cửa."},{"time":"Ngày 2 · 08:00–11:30","title":"Làng nghề và đời sống","description":"Gặp gỡ cơ sở làng nghề đang tiếp nhận khách."},{"time":"Ngày 2 · 13:00–15:00","title":"Khép lại hành trình","description":"Tổng kết trải nghiệm và kết thúc tại điểm hẹn."}]'::jsonb,
 'Cần đối soát vé di tích, giờ mở cửa, cơ sở làng nghề, nhà hàng, lưu trú, phương tiện và các lưu ý về thời tiết/mưa lũ.'),
 ('Hà Nội – ngõ nhỏ và ký ức phố','Miền Bắc','Khám phá Hà Nội qua kiến trúc, phố nghề, không gian công cộng và câu chuyện đời sống trong khu phố lâu đời.','Di sản đô thị',1,'Nửa ngày','Khu vực hồ Hoàn Kiếm; điểm hẹn xác nhận','Đi bộ; phương tiện nội đô khi cần',
 '[{"time":"08:00–08:30","title":"Gặp nhau bên hồ","description":"Giới thiệu tuyến đi bộ, quy tắc ứng xử và bối cảnh khu phố."},{"time":"08:30–10:00","title":"Ngõ phố và kiến trúc","description":"Quan sát cấu trúc phố, mặt tiền và các không gian công cộng; không tự ý vào khu vực riêng tư."},{"time":"10:00–11:00","title":"Phố nghề và câu chuyện mưu sinh","description":"Tìm hiểu nghề truyền thống qua điểm dừng đã được cơ sở đồng ý tiếp đón."},{"time":"11:00–11:30","title":"Ghi lại một Hà Nội riêng","description":"Tổng kết và gợi ý các tuyến khám phá tiếp theo."}]'::jsonb,
 'Cần xác minh tuyến đi bộ, điểm dừng được tiếp cận, lịch tiếp khách của cơ sở nghề và quy định giao thông/sự kiện.'),
 ('Ninh Bình – non nước và làng quê','Miền Bắc','Kết hợp cảnh quan karst, di sản và trải nghiệm nông thôn theo tuyến phù hợp điều kiện thời tiết.','Thiên nhiên – di sản',2,'2 ngày 1 đêm','TP. Ninh Bình hoặc Hà Nội; xác nhận khi vận hành','Xe du lịch; thuyền tại bến được cấp phép',
 '[{"time":"Ngày 1 · 08:00–11:30","title":"Cảnh quan Tràng An hoặc tuyến thay thế","description":"Chọn tuyến thuyền chính thức theo vé, điều kiện vận hành và thời tiết."},{"time":"Ngày 1 · 13:30–16:30","title":"Di sản và không gian làng quê","description":"Thăm điểm di sản phù hợp giờ mở cửa và sức khỏe đoàn."},{"time":"Ngày 2 · 07:30–10:30","title":"Buổi sáng giữa cảnh quan đá vôi","description":"Khám phá điểm ngắm cảnh/tuyến đi bộ có mức độ phù hợp; không áp dụng khi thời tiết nguy hiểm."},{"time":"Ngày 2 · 11:00–13:00","title":"Ẩm thực địa phương","description":"Dùng bữa tại cơ sở được xác nhận."},{"time":"Ngày 2 · 13:00–15:00","title":"Kết thúc hành trình","description":"Trở về điểm hẹn theo phương án vận chuyển."}]'::jsonb,
 'Cần xác minh tuyến thuyền, vé, điểm leo/đi bộ, lưu trú, bữa ăn, thời tiết và phương án thay thế trong ngày mưa.'),
 ('Sa Pa – bản làng và sắc núi','Miền Bắc','Tìm hiểu văn hóa bản địa và cảnh quan vùng cao theo cách tôn trọng cộng đồng, không biến sinh hoạt thường ngày thành màn trình diễn.','Cộng đồng – thiên nhiên',3,'3 ngày 2 đêm','Sa Pa; điểm đón xác nhận theo lưu trú','Xe du lịch; đi bộ theo tuyến cộng đồng',
 '[{"time":"Ngày 1 · 14:00–17:00","title":"Làm quen thị trấn và cảnh quan","description":"Đi bộ nhẹ, làm quen độ cao và điều kiện thời tiết."},{"time":"Ngày 2 · 08:00–12:00","title":"Tuyến đi bộ cộng đồng","description":"Đi cùng người dẫn đường địa phương trên tuyến được cộng đồng thống nhất; điều chỉnh theo thể lực."},{"time":"Ngày 2 · 13:30–16:30","title":"Tìm hiểu nghề và sinh hoạt","description":"Ghé cơ sở thủ công/nhà cộng đồng có lịch tiếp khách."},{"time":"Ngày 3 · 08:00–11:00","title":"Cảnh quan theo mùa","description":"Chọn điểm phù hợp mùa vụ và thời tiết; không cam kết mùa lúa/hoa cố định."},{"time":"Ngày 3 · 13:00–15:00","title":"Tổng kết và kết thúc","description":"Trở lại điểm hẹn, kết thúc chương trình."}]'::jsonb,
 'Cần xác minh cộng đồng đối tác, người dẫn đường, tuyến trekking, lưu trú, độ khó, bảo hiểm, thời tiết và nguyên tắc chia sẻ lợi ích địa phương.'),
 ('Hà Giang – cung đường đá và bản sắc','Miền Bắc','Hành trình nhiều ngày tìm hiểu cao nguyên đá, cảnh quan và văn hóa cộng đồng với ưu tiên an toàn và tôn trọng địa phương.','Khám phá – cộng đồng',4,'4 ngày 3 đêm','Hà Giang; điểm đón xác nhận theo phương án vận chuyển','Xe du lịch có lái xe đủ điều kiện; đi bộ ngắn',
 '[{"time":"Ngày 1 · 08:00–17:00","title":"Tiếp cận cao nguyên đá","description":"Di chuyển theo tuyến đường được đơn vị vận hành xác nhận; có điểm nghỉ phù hợp."},{"time":"Ngày 2 · 08:00–16:30","title":"Cảnh quan và câu chuyện địa chất","description":"Tham quan các điểm dừng được phép, không dừng xe tùy tiện trên đường đèo."},{"time":"Ngày 3 · 08:00–16:30","title":"Gặp gỡ văn hóa bản địa","description":"Hoạt động cùng đối tác cộng đồng đã thống nhất, tôn trọng phong tục và quyền riêng tư."},{"time":"Ngày 4 · 08:00–16:00","title":"Trở về và khép hành trình","description":"Di chuyển về điểm kết thúc theo điều kiện giao thông và thời tiết."}]'::jsonb,
 'Tuyến đường, điểm dừng và thời gian phải được đơn vị vận hành địa phương thẩm định. Cần đánh giá rủi ro đường đèo, thời tiết, phương tiện, bảo hiểm và phương án khẩn cấp.')
)
insert into public.journeys
(title,region,summary,price_from,is_published,tour_type,duration_days,duration_label,departure_point,transport,itinerary,operating_note,price_note,verified_at)
select d.title,d.region,d.summary,0,true,d.tour_type,d.duration_days,d.duration_label,d.departure_point,d.transport,d.itinerary,d.operating_note,
       'Chưa công bố. NÉP chỉ cập nhật giá sau khi xác nhận nhà cung cấp và dịch vụ.',null
from tour_data d
where not exists (select 1 from public.journeys j where j.title=d.title);
